// The full PPL/PPAER question bank (510 questions, 100% TP 12880 syllabus coverage),
// plus shuffle and lookup helpers used across the app.

export function shuffleArray(arr) {
  const copy = [...arr];
  for (let i = copy.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [copy[i], copy[j]] = [copy[j], copy[i]];
  }
  return copy;
}

export function applyOptionOrder(question, order) {
  return {
    ...question,
    options: order.map((i) => question.options[i]),
    correct: order.indexOf(question.correct),
    optionOrder: order,
  };
}

export function shuffleQuestionOptions(question) {
  return applyOptionOrder(question, shuffleArray(question.options.map((_, i) => i)));
}

