export const QUESTION_BY_ID = (() => {
  const map = {};
  Object.values(QUIZ_BANK).forEach((arr) => arr.forEach((q) => { map[q.id] = q; }));
  return map;
})();

export const QUESTION_BY_TEXT = (() => {
  const map = {};
  Object.values(QUIZ_BANK).forEach((arr) => arr.forEach((q) => { map[q.q] = q; }));
  return map;
})();

export const ID_PREFIX_TO_CATEGORY = { AL: "Air Law", NAV: "Navigation", MET: "Meteorology", AS: "Aircraft & Systems", HF: "Human Factors" };

export function categoryFromId(id) {
  return ID_PREFIX_TO_CATEGORY[id.split("-")[0]];
}
